# -*- coding: utf-8 -*-
"""Reading Lab -- reading-comprehension passages for the teen track (Levels 3-6).

One passage every third lesson (3, 6, 9, 12, 15, 18), written to the level's
proficiency band, the lesson's topic and grammar focus, with culturally rich
Gulf / Arab-world content for today's generation.  Length grows with the
level: L3 ~120 words, L4 ~150, L5 ~175, L6 ~210 -- a 3-4 minute read.

Each passage:
  title / title_ar   -- shown on the opener and the passage slide
  tag                -- a short topic label (culture, sport, school ...)
  images             -- two files in assets/reading/<level>/ with their
                        production prompts (the usual master style applies);
                        slides fall back to a styled tile until they exist
  before             -- 2 prediction questions for the teacher (pre-reading)
  paras              -- 4 paragraphs; 1-2 sit under image A (top-left),
                        3-4 sit beside image B (bottom-right).  Inline
                        pronunciation marks: [word](rule) -> glows on tap
  new                -- 2-3 words the student has NOT met yet, glossed
  questions          -- teacher questions only (no options): 2 "Find it"
                        (literal), 2 "Think" (inference), 2 "You" (personal)

Words the student has ALREADY studied are detected automatically from the
lesson JSONs (lib/reading_slides.py) and shown as glowing chips with their
Arabic meaning -- nothing to maintain here.
"""

# ---------------------------------------------------------------- pronunciation rules
# key: (title, explanation EN, explanation AR, examples)
RULES = {
    "silent": ("Silent letter", "One letter is written but not said.", "حرف يُكتب ولا يُنطق.", "know, climb, hour, listen, island"),
    "ed-t": ("-ed sounds like /t/", "After a quiet sound (k, p, s, sh, ch) the -ed ending is a short /t/.", "بعد صوت مهموس تُنطق -ed كـ /t/ قصيرة.", "walked, looked, finished, helped"),
    "ed-d": ("-ed sounds like /d/", "After a voiced sound (l, n, v, m, vowels) the -ed ending is a /d/.", "بعد صوت مجهور تُنطق -ed كـ /d/.", "played, called, arrived, cleaned"),
    "ed-id": ("-ed sounds like /ɪd/", "After t or d, -ed adds a whole extra syllable: /ɪd/.", "بعد t أو d تُضاف مقطعًا كاملًا /ɪd/.", "wanted, needed, visited, decided"),
    "th-v": ("Soft th /ð/", "Tongue between the teeth, voice ON -- like a buzzing ذ.", "اللسان بين الأسنان مع صوت -- مثل ذ.", "this, that, mother, together"),
    "th-s": ("Sharp th /θ/", "Tongue between the teeth, voice OFF -- like ث.", "اللسان بين الأسنان بدون صوت -- مثل ث.", "think, three, thing, birthday"),
    "magic-e": ("Magic e", "A final silent e makes the vowel before it say its name.", "حرف e الصامت في النهاية يجعل الحرف المتحرك قبله ينطق باسمه.", "make, time, home, late"),
    "ph": ("ph = /f/", "The letters ph are said as one sound: /f/.", "تُنطق ph كصوت واحد /f/.", "phone, photo, graph"),
    "soft-c": ("Soft c", "c before e, i or y sounds like /s/.", "حرف c قبل e أو i أو y يُنطق /s/.", "city, ice, nice, decide"),
    "soft-g": ("Soft g", "g before e, i or y often sounds like /dʒ/ (like ج).", "حرف g قبل e أو i أو y غالبًا يُنطق /dʒ/ مثل ج.", "giant, page, energy, village"),
    "ght": ("Silent gh", "In -ght the gh is silent; you only hear the t.", "في -ght لا يُنطق gh، تسمع t فقط.", "night, right, light, thought"),
    "tion": ("-tion = /ʃən/", "The ending -tion is said 'shun'.", "النهاية -tion تُنطق 'شن'.", "tradition, station, celebration"),
    "s-z": ("Plural s = /z/", "After a voiced sound the plural -s buzzes like /z/.", "بعد صوت مجهور تُنطق -s الجمع كـ /z/.", "friends, games, cousins, days"),
    "ch-k": ("ch = /k/", "In words from Greek, ch is said /k/.", "في الكلمات اليونانية الأصل تُنطق ch كـ /k/.", "school, chemistry, stomach"),
    "stress": ("Word stress", "Say the CAPITAL part louder and longer.", "انطق الجزء بالأحرف الكبيرة أعلى وأطول.", "beCAUSE, toGEther, imPORtant"),
    "schwa": ("The lazy vowel /ə/", "Unstressed vowels relax to a tiny 'uh' sound.", "الحروف المتحركة غير المشددة تُنطق كصوت 'أُه' قصير.", "about, camera, teacher"),
    "qu": ("qu = /kw/", "qu is always two sounds: /k/ + /w/.", "تُنطق qu دائمًا صوتين /k/ + /w/.", "question, quick, quiet"),
    "ea-ee": ("ea = /iː/", "ea usually says a long 'ee'.", "عادةً تُنطق ea كصوت 'إي' طويل.", "read, tea, dream, team"),
    "ou-ow": ("ou = /aʊ/", "ou often says 'ow' like in house.", "غالبًا تُنطق ou كـ 'آو' مثل house.", "house, about, proud, loud"),
    "wh": ("wh = /w/", "The h in wh- is silent; just say /w/.", "حرف h في wh- صامت؛ انطق /w/ فقط.", "what, where, when, while"),
    "link": ("Linking", "A final consonant joins the next vowel: 'an_apple'.", "الحرف الساكن الأخير يرتبط بالحرف المتحرك التالي.", "turn_off, pick_it_up"),
    "ea-e": ("ea = /e/", "In some common words ea is a short 'e'.", "في بعض الكلمات الشائعة تُنطق ea كـ 'إ' قصيرة.", "bread, ready, breakfast, head"),
    "ou-u": ("ou = /ʌ/", "In a few common words ou is a short 'uh'.", "في كلمات شائعة قليلة تُنطق ou كـ 'أ' قصيرة.", "cousin, country, young, double"),
}

